head.script:
window.CookieConsent.init({
  modalMainTextMoreLink: 'https://disgenet.com/Cookies-policy',
  enableBarMainCookiePolicy: false,
  barTimeout: 300,
  theme: {
    barColor: '#343a40',
    barTextColor: '#FFF',
    barMainButtonColor: '#17a2b8',
    barMainButtonTextColor: '#fff',
    modalMainButtonColor: '#17a2b8',
    modalMainButtonTextColor: '#fff',
  },
  language: {
    current: 'en',
    locale: {
      en: {
        barMainText: `We use our own and third-party cookies to enable the website's basic functions. Preference and analytical cookies are optional and will only be installed if you give your consent. `,
        barMainCookiePolicyLink: 'https://disgenet.com/Cookies-policy',
        barMainCookiePolicyTitle: 'Click here for more information.',
        barLinkSetting: 'Cookie settings',
        barBtnAcceptAll: 'Accept all cookies',
        modalMainTitle: 'Cookie settings',
        modalMainText: `We use cookies to track how our Website is being used so we can optimize its functioning. For users who have created an account, the cookies save their website preferences. `,
        modalMainTextMoreTitle: 'Click here for more information.',
        modalBtnSave: 'Save current settings',
        modalBtnAcceptAll: 'Accept all cookies and close',
        modalAffectedSolutions: 'Affected solutions:',
        learnMore: 'Learn More',
        on: 'On',
        off: 'Off',
      },
    },
  },
  categories: {
    necessary: {
      needed: true,
      wanted: true,
      checked: true,
      language: {
        locale: {
          en: {
            name: 'TECHNICAL COOKIES (STRICTLY NECESSARY)',
            description: `These cookies are essential for the proper functioning of the website and cannot be disabled. They enable core functionalities such as security, network management and accessibility. The legal basis that allows us to collect your data through these cookies is our legitimate interest in managing our website.`,
          },
        },
      },
    },
    preferences: {
      needed: false,
      wanted: false,
      checked: false,
      language: {
        locale: {
          en: {
            name: 'PREFERENCE COOKIES (OPTIONAL)',
            description: `Preference cookies are optional and require your consent. They allow the website to remember your settings or choices, such as your cookie preferences. These cookies are turned off by default. The legal basis for processing these cookies is your consent.`,
          },
        },
      },
    },
    analytics: {
      needed: false,
      wanted: false,
      checked: false,
      language: {
        locale: {
          en: {
            name: 'ANALYTICS COOKIES (OPTIONAL)',
            description: `These cookies allow monitoring and analyzing the behavior of web users. The information collected through this type of cookies is used to measure the activity of the website, application, or platform and to create navigation profiles of the users of those websites, applications, and platforms, in order to improve the website and our service offerings. The legal basis that allows us to collect your data through these cookies is your consent.`,
          },
        },
      },
    },
  },
  // List actual services here
  // 'dynamic-script'
  services: {
    googleAnalytics: {
      category: 'analytics',
      type: 'dynamic-script',
      search: 'analytics',
      cookies: [
        {
          name: /^_gid/,
          domain: `.${window.location.hostname}`,
        },
        {
          name: /^_ga/,
          domain: `.${window.location.hostname}`,
        },
        {
          name: /^_dc_gtm/,
          domain: `.${window.location.hostname}`,
        },
      ],
      language: {
        locale: {
          en: {
            name: 'Google Analytics',
          },
        },
      },
    },
  },
});
